CREATE TABLE `producto` (
  `id_producto` int(11) NOT NULL AUTO_INCREMENT,
  `titulo` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `descripcion` text NOT NULL,
  `sku` varchar(100) DEFAULT NULL,
  `odoo_id` int(11) DEFAULT NULL,
  `id_marca` int(11) DEFAULT NULL,
  `cuotas_max` int(11) DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_producto`),
  UNIQUE KEY `producto_slug_key` (`slug`),
  UNIQUE KEY `producto_odoo_id_key` (`odoo_id`),
  KEY `producto_id_marca_fkey` (`id_marca`),
  CONSTRAINT `producto_id_marca_fkey` FOREIGN KEY (`id_marca`) REFERENCES `marca` (`id_marca`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=777 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
